import{z as o,x as s,o as A,c as d,q as B,j as t,D as r,d as e,s as i,S as n,b as E}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"偏好强度的标定","description":"","frontmatter":{"title":"偏好强度的标定","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/preference-strength-calibration.md","filePath":"llm/preference-strength-calibration.md","lastUpdated":1791063341000}'),p={name:"llm/preference-strength-calibration.md"};function m(C,a,D,_,c,h){const l=s("Mermaid");return A(),d("div",null,[a[2]||(a[2]=B('<h1 id="偏好强度的标定" tabindex="-1">偏好强度的标定 <a class="header-anchor" href="#偏好强度的标定" aria-label="Permalink to &quot;偏好强度的标定&quot;">​</a></h1><div class="epigraph"><p>「A 比 B 好」和「A 比 B 好得多」在二元标签里是同一行数据；把强度扔掉，等于把噪声对和金子对同等加权。</p><footer>—— 强度采集与加权见 Wang 等 Secrets of RLHF Part II 2024、Cui 等 UltraFeedback 2023；概率底座见 Bradley-Terry</footer></div><p><a href="/llm/annotation-agreement">上一课</a>把分歧归因时留了一个出口：真模糊的对降权或「转强度档」。本课把那个档位补完：偏好强度怎么采、怎么变成损失里的量、怎么反过来清洗标签。二元标签是 BT 损失的接口，但标注员判断里天然带着强度——把「险胜」与「碾压」都记成 1，是采集端最大的一笔信息丢弃。<a href="/llm/bradley-terry">Bradley-Terry</a> 的潜在分数本来就允许间隙存在，本课讨论怎么把间隙请回损失。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>无强度的损失对所有对一视同仁：\\(\\mathcal{L}=-\\log\\sigma(r_w-r_l)\\) 里，标注员犹豫再三的险胜和一眼定案的碾压给出同样长的梯度。这带来两类错。第一类是权重错配：数据池里大部分对本来就是容易对，训练被容易对支配，难对（真正界定分辨边界的那些）贡献占比失衡。第二类更隐蔽：险胜对里混着大量翻转噪声——上一课的机制面说过，难分的对恰好是标签最不可靠的对，不加区分地全权重训练，等于在最不可信的数据上花最多梯度。不这么做会错在哪：RM 学到一堆弱偏好的大间隙，分数的尺度被噪声撑大，下游 RL 的优势估计跟着被污染。</p><p><span class="marginnote">数字实例：碾压对（真实差距约 \\(4\\)）在 \\(\\sigma(4)\\approx 0.98\\) 处梯度已近零，基本不再贡献更新；险胜对（差距约 \\(0.1\\)）反而拿到最大梯度。不加权重时，训练火力自动集中在最不可信的对上。</span></p><h3 id="强度怎么采" tabindex="-1">强度怎么采 <a class="header-anchor" href="#强度怎么采" aria-label="Permalink to &quot;强度怎么采&quot;">​</a></h3><p>两端口径。标注端：在赢/输之外加强度档，常见四级——明显更好、稍好、差不多、不确定；UltraFeedback 让裁判模型按细粒度维度打分再综合，Secrets of RLHF 用多裁判与一致性反推强度。两端的共同点是把「有多确定」从标注员的肌肉记忆里显式地问出来，而不是丢掉。协议上强度档要进指南、配案例：什么算「明显」，要用示例对钉住，否则档位只反映标注员的个人尺度（上一课一致性的教训在强度上更严重，因为档更多）。</p>',8)),(A(),t(n,null,{default:r(()=>[i(l,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20PAIR%5B%22%E6%AF%94%E8%BE%83%E5%AF%B9%20%2B%20%E5%BC%BA%E5%BA%A6%E6%A1%A3%22%5D%20--%3E%20CLEAN%7B%22%E6%B8%85%E6%B4%97%EF%BC%9A%E5%BC%BA%E5%BA%A6%E4%B8%8E%E5%A4%9A%E8%A3%81%E5%88%A4%E6%98%AF%E5%90%A6%E5%86%B2%E7%AA%81%22%7D%0A%20%20CLEAN%20--%3E%7C%E7%BF%BB%E8%BD%AC%E5%AB%8C%E7%96%91%7C%20FLIP%5B%22%E4%BF%AE%E6%AD%A3%E6%88%96%E4%B8%A2%E5%BC%83%22%5D%0A%20%20CLEAN%20--%3E%7C%E9%80%9A%E8%BF%87%7C%20W%5B%22%E6%9D%83%E9%87%8D%20w%EF%BC%9A%E7%A2%BE%E5%8E%8B%E9%AB%98%E3%80%81%E9%99%A9%E8%83%9C%E4%BD%8E%22%5D%0A%20%20FLIP%20--%3E%20W%0A%20%20W%20--%3E%20LOSS%5B%22%E5%8A%A0%E6%9D%83%E6%8D%9F%E5%A4%B1%20-w%C2%B7log%20%CF%83(r_w%20-%20r_l)%22%5D%0A%20%20LOSS%20--%3E%20RM%5B%22RM%20%E5%88%86%E6%95%B0%E9%97%B4%E9%9A%99%20%E2%89%88%20%E5%BC%BA%E5%BA%A6%E5%BA%8F%22%5D%0A%20%20RM%20--%3E%20CAL%5B%22%E4%B8%8B%E6%B8%B8%EF%BC%9A%E4%BC%98%E5%8A%BF%E4%BC%B0%E8%AE%A1%E4%B8%8E%E6%A0%A1%E5%87%86%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("h2",{id:"方法",tabindex:"-1"},[e("方法 "),E("a",{class:"header-anchor",href:"#方法","aria-label":'Permalink to "方法"'},"​")],-1)),a[4]||(a[4]=E("p",null,[e("强度进训练有三条路。加权：\\(\\mathcal{L}=-\\sum_i w_i\\log\\sigma(\\Delta_i)\\) ，碾压对 \\(w\\) 大、险胜对 \\(w\\) 小，\\(w\\) 从强度档映射，也从翻转嫌疑反推（强度标「差不多」却被记成硬胜负的对降权）。加间隔：\\(\\sigma(\\Delta_i-m_i)\\) 把强度转成目标间隙 \\(m_i\\)，比加权更直接地约束尺度。软标签：把强度档转成期望胜率 \\(p\\)，损失写成 \\(-p\\log\\sigma(\\Delta)-(1-p)\\log\\sigma(-\\Delta)\\)，保持 BT 概率语义，与校准（"),E("a",{href:"/llm/rm-calibration"},"RM 校准"),e("）衔接最顺。三条路都先过清洗：强度信息最大的工程价值不在加权，而在它是免费的标签质检器——强度与最终标签矛盾的对，就是翻转嫌疑对。")],-1)),a[5]||(a[5]=E("p",null,[E("span",{class:"marginnote"},"术语翻译：「软标签」就是把「A 赢了」改成「A 以八成概率赢」——标签从 0/1 硬值变成 0 到 1 的连续值，模型只需把预测概率对准 \\(p\\)，不必硬顶到 1。")],-1)),(A(),t(n,null,{default:r(()=>[i(l,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20TD%0A%20%20S%5B%22%E5%BC%BA%E5%BA%A6%E6%A1%A3%EF%BC%9A%E7%A2%BE%E5%8E%8B%20%2F%20%E7%A8%8D%E5%A5%BD%20%2F%20%E5%B7%AE%E4%B8%8D%E5%A4%9A%22%5D%20--%3E%20A%5B%22%E8%B7%AF%E4%B8%80%EF%BC%9A%E5%8A%A0%E6%9D%83%20w_i%22%5D%0A%20%20S%20--%3E%20B%5B%22%E8%B7%AF%E4%BA%8C%EF%BC%9A%E7%9B%AE%E6%A0%87%E9%97%B4%E9%9A%94%20m_i%22%5D%0A%20%20S%20--%3E%20C%5B%22%E8%B7%AF%E4%B8%89%EF%BC%9A%E8%BD%AF%E6%A0%87%E7%AD%BE%E6%9C%9F%E6%9C%9B%E8%83%9C%E7%8E%87%20p_i%22%5D%0A%20%20A%20--%3E%20D%5B%22%E9%97%B4%E9%9A%99%E6%81%A2%E5%A4%8D%E8%AF%AD%E4%B9%89%EF%BC%9A%E7%A2%BE%E5%8E%8B%E6%8B%89%E5%BC%80%E3%80%81%E9%99%A9%E8%83%9C%E6%94%B6%E7%AA%84%22%5D%0A%20%20B%20--%3E%20D%0A%20%20C%20--%3E%20D%0A%20%20D%20--%3E%20E%5B%22%E4%B8%8B%E6%B8%B8%E4%BC%98%E5%8A%BF%E9%87%8F%E7%BA%A7%E4%B8%8D%E5%86%8D%E8%A2%AB%E5%99%AA%E5%A3%B0%E6%92%91%E7%88%86%22%5D%0A"})]),fallback:r(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=B('<p>这张图回答「同一份强度档怎么进损失」：三条路口径不同，落点都是把分数尺度拉回与人的强度序一致。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>强度为什么承载噪声信息：BT 模型里比较结果 \\(P(w\\succ l)=\\sigma(r_w-r_l)\\)，标注员报告的强度是这个概率的主观估计。「险胜」意味着 \\(r_w-r_l\\) 接近 0，该对落在判别边界附近——恰好是翻转率最高、梯度噪声最大的区域。压低它的权重，梯度期望几乎不变（边界附近的对两种标签各半，贡献互相抵消），方差显著下降，等价于做了免费的方差缩减。同时，「明显更好」的对把间隙拉开，分数尺度恢复语义，下游 RL 里优势 \\(\\hat A\\) 的量级不再被噪声对撑爆——这与后课「奖励方差与策略稳定性」直接相连：数据端的强度标定是策略端稳定性的第一道闸。</p><p><span class="marginnote">反推口径：不额外问标注员，也可用多个独立裁判（或多个 RM）的分歧度当强度代理——全员同向为「碾压」，分裂为「差不多」。成本是多次前向，好处是强度与主标签同源，协议不用加档位。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>强度标尺跨人不可比：A 的「明显」是 B 的「稍好」，所以强度档主要用于同标注员内部的相对加权，或按标注员分层归一后再用；跨员直接混档会引入新的系统偏差。强度也不能替代一致性与仲裁：档位只是多一路测量，噪声对仍是噪声对，翻转嫌疑要送上一课的仲裁流程而不是自动清洗——自动清洗会把难例整个赶出数据集，RM 的边界随之退化。最后，强度进损失的幅度要消融：权重压得过狠，训练分布被「容易对」主导，验证准确率看着高，边界附近反而更糊。强度是先验不是真值，这是本课全部方法的适用前提。</p><p><span class="marginnote">常见误区：把「差不多」的对直接从数据集里扔掉。降权是「小声说话」，丢弃是「闭嘴」——全丢之后训练集只剩容易对，边界附近没有任何监督，RM 恰恰在最需要它表态的地方失去分辨力。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>二元标签丢掉强度；强度档是采集端最便宜的增量信息，案例必须写进指南。</li><li>强度有三条进损失的路：加权、目标间隔、软标签，均保持 BT 概率语义。</li><li>机制上强度是噪声探测器：边界附近的对翻转率高，降权是免费的方差缩减。</li><li>间隙恢复语义后，下游优势估计与校准都受益；幅度要消融。</li><li>出处：Wang 等 Secrets of RLHF Part II，2024；Cui 等 UltraFeedback，2023；Bradley-Terry 底座见主干课。</li></ul>',9))])}const u=o(p,[["render",m]]);export{f as __pageData,u as default};
